window.kbPageData["views/entry/k-3941eb78632b15f1"] = {"key":"entry/k-3941eb78632b15f1","state":{"route":"entry/k-3941eb78632b15f1"},"node":{"id":"k-3941eb78632b15f1","mode":"k","title":"虫蛀痕迹与蘑菇毒性","type":"原理与机制","domain":"科技","reading":"","intro":"","priority":100,"aliases":["虫子取食痕迹不足以判断蘑菇对人体的毒性"],"qs":["国考 2023 地市级 行测#20"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"蘑菇中的毒素对不同动物的影响可能不同。虫子能够取食某种蘑菇，无法据此判断这种蘑菇对人体的毒性。","review":{"definition":"蘑菇中的毒素对不同动物的影响可能不同。虫子能够取食某种蘑菇，无法据此判断这种蘑菇对人体的毒性。","explanation":"解析举出对人有毒的白毒伞也有虫啮记录，说明对人有毒的蘑菇同样可能留下取食痕迹。D项把虫子取食痕迹当作辨毒依据，因此是本题要求选出的错误说法。","references":[],"evidence":"白毒伞也有被虫啮食的记录","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 地市级 行测#20":{"paper":"国考 2023 地市级 行测","n":20,"mod":"常识判断","src":["64bc3a15d27a04e94940.pdf",3],"asrc":["f3ab652d8e31c5bbdabc.pdf",8],"card":"ccb1f3832cc15793940511c1","links":[{"id":"k-3941eb78632b15f1","role":"直接考查","why":"对人有毒的蘑菇也可能被虫取食，因此虫啮痕迹不足以判断人体食用安全性。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-3941eb78632b15f1":[["国考 2023 地市级 行测#20"]]}};
